/**
 * Shared domain models for DisasterMesh AI.
 *
 * Phase 0 defines shapes only. Nothing here reads or writes storage,
 * and nothing here performs synchronization or agent decisions.
 *
 * Assumption: identifiers are opaque strings generated by a later local service.
 * Assumption: locations are WGS84 latitude/longitude until a richer geometry type is needed.
 */

/** Whether a report has been checked by a person in the field. */
export type VerificationStatus = "unverified" | "verified" | "disputed";

/**
 * Envelope for a locally recorded change.
 *
 * `observedAt` is when the condition was seen in the world.
 * `createdAt` is when this device wrote the record. They can differ
 * when a report is entered after the fact or received from another peer later.
 */
export interface EventEnvelope<TPayload = unknown> {
  eventId: string;
  eventType: "create" | "update" | "delete";
  sourcePeerId: string;
  entityId: string;
  observedAt: string;
  createdAt: string;
  version: number;
  verificationStatus: VerificationStatus;
  payload: TPayload;
}

export type ConnectivityStatus = "online" | "offline" | "degraded";

export interface Peer {
  peerId: string;
  displayName: string;
  role: string;
  connectivityStatus: ConnectivityStatus;
  /** ISO-8601 timestamp of the last contact this device recorded. */
  lastSeenAt: string;
}

export type IncidentType =
  | "flood"
  | "fire"
  | "earthquake"
  | "landslide"
  | "structural_collapse"
  | "medical"
  | "hazard"
  | "blocked_route"
  | "other";

export type IncidentSeverity = "critical" | "high" | "medium" | "low";

export type IncidentStatus = "open" | "monitoring" | "resolved";

export interface GeoPoint {
  /** Present only when the reporter supplied coordinates. */
  latitude?: number;
  longitude?: number;
  label?: string;
}

export interface Incident {
  incidentId: string;
  title: string;
  description: string;
  incidentType: IncidentType;
  severity: IncidentSeverity;
  location: GeoPoint;
  /** Human label entered with the report. Not proof of identity. */
  reportedBy: string;
  /** Simulated peer that owns this record. Isolation key. */
  sourcePeerId: string;
  createdAt: string;
  status: IncidentStatus;
  verificationStatus: VerificationStatus;
}

export type TaskPriority = "critical" | "high" | "medium" | "low";

export type TaskStatus = "pending" | "assigned" | "in_progress" | "completed" | "cancelled";

export interface RescueTask {
  taskId: string;
  title: string;
  description: string;
  priority: TaskPriority;
  status: TaskStatus;
  assignedPeerId: string | null;
  relatedIncidentId: string | null;
  createdAt: string;
}

export interface SupplyItem {
  itemId: string;
  itemName: string;
  quantityAvailable: number;
  unit: string;
  location: GeoPoint;
  updatedAt: string;
  sourcePeerId: string;
}

export type SpatialUpdateType = "hazard" | "blocked_route" | "safe_zone" | "shelter";

export interface SpatialUpdate {
  spatialUpdateId: string;
  updateType: SpatialUpdateType;
  /** Point plus optional radius in meters. A later phase may replace this with a geometry union. */
  geometry: GeoPoint & { radiusMeters?: number };
  description: string;
  sourcePeerId: string;
  observedAt: string;
  verificationStatus: VerificationStatus;
}

export type ConflictStatus = "unresolved" | "resolved";

export type ConflictType = "concurrent_update" | "inventory_reservation" | "stale_version";

/**
 * A disagreement between two or more events about the same entity.
 * Resolution behavior is intentionally not implemented in Phase 0.
 */
export interface ConflictRecord {
  conflictId: string;
  entityId: string;
  conflictingEventIds: string[];
  conflictType: ConflictType;
  status: ConflictStatus;
  resolutionNotes: string | null;
}

export type AppSection =
  | "overview"
  | "incidents"
  | "tasks"
  | "supplies"
  | "map"
  | "peers"
  | "agents"
  | "sync"
  | "events"
  | "conflicts"
  | "tests";
